    "childDialects": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "accepted",
        "refused"
      ],
      "properties": {
        "accepted": {
          "type": "array",
          "minItems": 2,
          "maxItems": 2,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "artifactKind",
              "standard",
              "subset"
            ],
            "properties": {
              "artifactKind": {
                "type": "string"
              },
              "standard": {
                "type": "string"
              },
              "subset": {
                "type": "string"
              }
            }
          }
